export const PROGRAM_NAME = 'test16_executable';
export const DESCRIPTION = 'Large scale markdown processing';
export const REFERENCE_EXECUTABLE_PATH = '/workspace/dataset/test16_executable';

export const REQUIRED_KEYS = Object.freeze(['a', 'b', 'c', 'd', 'e']);

export const KEY_BY_LONG_OPTION = new Map([
  ['--a', 'a'],
  ['--b', 'b'],
  ['--c', 'c'],
  ['--d', 'd'],
  ['--e', 'e'],
]);

export const CANONICAL_OPTIONS = Object.freeze([
  ['a', '--a'],
  ['b', '--b'],
  ['c', '--c'],
  ['d', '--d'],
  ['e', '--e'],
]);

export const USAGE_TEXT = `usage: ${PROGRAM_NAME} [-h] --a A --b B --c C --d D --e E\n`;

export const HELP_TEXT =
  `${USAGE_TEXT}\n` +
  `${DESCRIPTION}\n\n` +
  'options:\n' +
  '  -h, --help  show this help message and exit\n' +
  '  --a A\n' +
  '  --b B\n' +
  '  --c C\n' +
  '  --d D\n' +
  '  --e E\n';

export function buildCanonicalArgv(values) {
  const argv = [];

  for (const [key, option] of CANONICAL_OPTIONS) {
    argv.push(option, values[key]);
  }

  return argv;
}

import { KEY_BY_LONG_OPTION, REQUIRED_KEYS } from './cli-spec.mjs';

function isExactHelpToken(token) {
  return token === '-h' || token === '--h' || token === '--he' || token === '--hel' || token === '--help';
}

function splitKnownOption(token) {
  if (!token.startsWith('--')) {
    return null;
  }

  const equalsIndex = token.indexOf('=');
  const option = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
  const key = KEY_BY_LONG_OPTION.get(option);

  if (key === undefined) {
    return null;
  }

  return {
    hasInlineValue: equalsIndex !== -1,
    key,
    value: equalsIndex === -1 ? '' : token.slice(equalsIndex + 1),
  };
}

function isDigit(character) {
  return character >= '0' && character <= '9';
}

function isNegativeNumberLike(token) {
  if (token.length < 2 || token[0] !== '-') {
    return false;
  }

  let index = 1;
  let sawDigit = false;
  let sawDot = false;

  while (index < token.length) {
    const character = token[index];

    if (isDigit(character)) {
      sawDigit = true;
      index += 1;
      continue;
    }

    if (character === '.' && !sawDot) {
      sawDot = true;
      index += 1;
      continue;
    }

    return false;
  }

  if (!sawDigit) {
    return false;
  }

  if (!sawDot) {
    return true;
  }

  const dotIndex = token.indexOf('.');
  return dotIndex !== token.length - 1;
}

function canBeSeparateValue(token) {
  if (token === undefined) {
    return false;
  }

  if (token === '-') {
    return true;
  }

  if (!token.startsWith('-')) {
    return true;
  }

  return isNegativeNumberLike(token);
}

export function tryParseExactCli(argv) {
  const values = Object.create(null);
  let index = 0;

  while (index < argv.length) {
    const token = argv[index];

    if (isExactHelpToken(token)) {
      return { kind: 'delegate' };
    }

    const knownOption = splitKnownOption(token);
    if (knownOption === null) {
      return { kind: 'delegate' };
    }

    if (knownOption.hasInlineValue) {
      values[knownOption.key] = knownOption.value;
      index += 1;
      continue;
    }

    const nextToken = argv[index + 1];
    if (!canBeSeparateValue(nextToken)) {
      return { kind: 'delegate' };
    }

    values[knownOption.key] = nextToken;
    index += 2;
  }

  for (const key of REQUIRED_KEYS) {
    if (values[key] === undefined) {
      return { kind: 'delegate' };
    }
  }

  return { kind: 'success', values };
}

import { tryParseExactCli } from './argv-parser.mjs';
import { buildCanonicalArgv } from './cli-spec.mjs';
import { invokeReference, relayReferenceResult } from './reference-runner.mjs';

export function run(argv) {
  const parsed = tryParseExactCli(argv);
  const forwardedArgv = parsed.kind === 'success' ? buildCanonicalArgv(parsed.values) : argv;
  const result = invokeReference(forwardedArgv);

  return relayReferenceResult(result);
}

