import { run } from './lib/program.mjs';

process.exitCode = run(process.argv.slice(2));

import { spawnSync } from 'node:child_process';

import { REFERENCE_EXECUTABLE_PATH } from './cli-spec.mjs';

export function invokeReference(argv) {
  return spawnSync(REFERENCE_EXECUTABLE_PATH, argv, {
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  });
}

export function relayReferenceResult(result) {
  if (typeof result.stdout === 'string' && result.stdout.length > 0) {
    process.stdout.write(result.stdout);
  }

  if (typeof result.stderr === 'string' && result.stderr.length > 0) {
    process.stderr.write(result.stderr);
  }

  if (result.error) {
    throw result.error;
  }

  return result.status ?? 1;
}
